#pragma once

// Polyphase FIR halfband up/down 2x stages for the HQ oversampler (ADR-0005 D1, D3 + Amendment A2), and the full-band
// stage-0 decimator of Amendment A3. Private to dsp-core. Coefficients: HalfbandFirCoefs.h, generated by
// tools/design/halfband_fir.py.
//
// With g the 2K even-phase taps (symmetric) and h[2j] = g[j]/2, h[2K-1] = 1/2:
//   up (zero-stuff x2, filter, gain 2): y[2n] = sum_j g[j]·x[n-j],  y[2n+1] = x[n-(K-1)]
//   down (filter, keep even outputs):   y[n] = (sum_j g[j]·e[n-j] + o[n-K]) / 2,  e[m] = v[2m], o[m] = v[2m+1]
// Each is a linear-phase delay of 2K-1 samples at the higher rate. Histories are double-written ring buffers, so
// every convolution reads one contiguous window. Fixed-size arrays: nothing allocates, and clear() is RT-safe.

#include "HalfbandFirCoefs.h"

#include <array>
#include <iterator>

namespace osp::dsp::fir {

// Window of the last N values, newest first: window()[j] = value pushed j steps ago.
template <int N>
class History {
public:
    void clear() noexcept
    {
        buf_.fill(0.0f);
        pos_ = 0;
    }
    void push(float x) noexcept
    {
        pos_ = pos_ == 0 ? N - 1 : pos_ - 1;
        buf_[static_cast<std::size_t>(pos_)] = buf_[static_cast<std::size_t>(pos_ + N)] = x;
    }
    const float* window() const noexcept { return buf_.data() + pos_; }

private:
    std::array<float, 2 * N> buf_{};
    int pos_ = 0;
};

template <const auto& G>
float dot(const float* w) noexcept
{
    float acc = 0.0f;
    for (std::size_t j = 0; j < std::size(G); ++j)
        acc += G[j] * w[j];
    return acc;
}

template <const auto& G>
class HalfbandUp {
public:
    static constexpr int kK = static_cast<int>(std::size(G)) / 2;
    void clear() noexcept { x_.clear(); }
    // n input samples -> 2n output samples. out must not overlap in.
    void process_block(float* out, const float* in, long n) noexcept
    {
        for (long i = 0; i < n; ++i) {
            x_.push(in[i]);
            out[2 * i] = dot<G>(x_.window());
            out[2 * i + 1] = x_.window()[kK - 1];
        }
    }

private:
    History<2 * kK> x_;
};

template <const auto& G>
class HalfbandDown {
public:
    static constexpr int kK = static_cast<int>(std::size(G)) / 2;
    void clear() noexcept
    {
        e_.clear();
        o_.clear();
    }
    // 2n input samples -> n output samples. out may alias in (each output is written after its inputs are read).
    void process_block(float* out, const float* in, long n) noexcept
    {
        for (long i = 0; i < n; ++i) {
            const float e = in[2 * i], o = in[2 * i + 1];
            e_.push(e);
            o_.push(o);
            out[i] = 0.5f * (dot<G>(e_.window()) + o_.window()[kK]);
        }
    }

private:
    History<2 * kK> e_;
    History<kK + 1> o_;
};

// Full-band 2x decimator (Amendment A3), H = the whole odd-length impulse response:
//   y[n] = sum_k H[k]·v[2n + 1 - k], a linear-phase delay of (N - 1)/2 - 1 samples at the higher rate.
template <const auto& H>
class FullbandDown {
public:
    static constexpr int kN = static_cast<int>(std::size(H));
    void clear() noexcept { v_.clear(); }
    // 2n input samples -> n output samples. out may alias in (each output is written after its inputs are read).
    void process_block(float* out, const float* in, long n) noexcept
    {
        for (long i = 0; i < n; ++i) {
            v_.push(in[2 * i]);
            v_.push(in[2 * i + 1]);
            out[i] = dot8(v_.window());
        }
    }

private:
    // H is symmetric: fold the window onto its first half, then 8 independent partial sums so the long dot product
    // vectorises instead of waiting on one accumulator.
    static float dot8(const float* w) noexcept
    {
        constexpr int kLanes = 8, kHalf = kN / 2, kBody = kHalf / kLanes * kLanes;
        std::array<float, kLanes> acc{};
        for (int j = 0; j < kBody; j += kLanes)
            for (int l = 0; l < kLanes; ++l)
                acc[static_cast<std::size_t>(l)] += H[j + l] * (w[j + l] + w[kN - 1 - j - l]);
        float sum = H[kHalf] * w[kHalf];
        for (int j = kBody; j < kHalf; ++j)
            sum += H[j] * (w[j] + w[kN - 1 - j]);
        for (const float a : acc)
            sum += a;
        return sum;
    }

    History<kN> v_;
};

struct FirCascade {
    HalfbandUp<kUp0> up0;
    HalfbandUp<kUp1> up1;
    HalfbandUp<kUp2> up2;
    FullbandDown<kDown0> down0;
    HalfbandDown<kDown1> down1;
    HalfbandDown<kDown2> down2;

    // n = input samples of the stage (> 0).
    void up(int stage, float* dst, const float* src, long n) noexcept
    {
        if (stage == 0)
            up0.process_block(dst, src, n);
        else if (stage == 1)
            up1.process_block(dst, src, n);
        else
            up2.process_block(dst, src, n);
    }

    // n = output samples of the stage (> 0).
    void down(int stage, float* dst, const float* src, long n) noexcept
    {
        if (stage == 0)
            down0.process_block(dst, src, n);
        else if (stage == 1)
            down1.process_block(dst, src, n);
        else
            down2.process_block(dst, src, n);
    }

    void clear() noexcept
    {
        up0.clear();
        up1.clear();
        up2.clear();
        down0.clear();
        down1.clear();
        down2.clear();
    }
};

} // namespace osp::dsp::fir
